"""Render retained attack-response and protocol-transfer observations."""
import argparse
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "artifact/figures"))
import csv
import io

HERE = Path(__file__).resolve().parent


ROOT = HERE.parent


def retained_rows(relative, expected=None):
    """Read inert retained columns; do not execute artifact code."""
    text = (ROOT / relative).read_text(encoding="utf-8-sig")
    if "," in text.splitlines()[0]:
        rows = list(csv.DictReader(io.StringIO(text)))
    else:
        lines = [s.split() for s in text.splitlines() if s.strip()]
        rows = [dict(zip(lines[0], s, strict=True)) for s in lines[1:]]
    if expected is not None and rows != expected:
        raise ValueError("Retained figure input changed: " + relative)
    return rows


