def read_checked(relative):
    text=(ROOT/relative).read_text(encoding="utf-8-sig").replace("\r\n","\n")
    if text.strip()!=SNAPSHOTS[relative].strip():
        raise ValueError("Retained plot data changed: "+relative)
    return retained_rows(relative)


def draw():
    from mark_panels import protocol_transfer
    from render_attack_response import render as attack_response
    attack_response(reader=lambda path:read_checked('figdata/'+path))
    protocol_transfer(HERE/'protocol-transfer.pdf',read_checked)


if __name__ == "__main__":
    draw()
